// Directions: up, down, left, right
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};
char dirChar[] = {'^', 'v', '<', '>'};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int H, W;
    cin >> H >> W;
    vector<string> grid(H);
    int tx = -1, ty = -1, dir = -1;

    // Read initial map and find tank position and direction
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '^') { tx = i; ty = j; dir = 0; }
            else if (grid[i][j] == 'v') { tx = i; ty = j; dir = 1; }
            else if (grid[i][j] == '<') { tx = i; ty = j; dir = 2; }
            else if (grid[i][j] == '>') { tx = i; ty = j; dir = 3; }
        }
    }

    string commands;
    cin >> commands;

    // Process each command
    for (char c : commands) {
        if (c == 'U') {
            dir = 0;
        } else if (c == 'D') {
            dir = 1;
        } else if (c == 'L') {
            dir = 2;
        } else if (c == 'R') {
            dir = 3;
        } else if (c == 'S') {
            // Shoot: find first obstacle in current direction
            int nx = tx, ny = ty;
            while (true) {
                nx += dx[dir];
                ny += dy[dir];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) break;
                if (grid[nx][ny] == '*') {
                    grid[nx][ny] = '.';
                    break;
                }
                if (grid[nx][ny] == '#') break;
            }
            continue; // no movement after shooting
        }

        // Move one step in current direction if possible
        int nx = tx + dx[dir];
        int ny = ty + dy[dir];
        if (nx >= 0 && nx < H && ny >= 0 && ny < W && grid[nx][ny] == '.') {
            grid[tx][ty] = '.';
            tx = nx;
            ty = ny;
        }
        // Place tank with updated direction
        grid[tx][ty] = dirChar[dir];
    }

    // Output final map
    for (int i = 0; i < H; i++) {
        cout << grid[i] << '\n';
    }

    return 0;
}

