int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int H, W;
        cin >> H >> W;

        vector<string> board(H);
        int r = -1, c = -1;

        for (int i = 0; i < H; ++i) {
            cin >> board[i];
            for (int j = 0; j < W; ++j) {
                if (board[i][j] == '^' || board[i][j] == 'v' || board[i][j] == '<' || board[i][j] == '>') {
                    r = i;
                    c = j;
                }
            }
        }

        int N;
        string cmd;
        cin >> N >> cmd;

        auto shoot = [&](int dr, int dc) {
            int nr = r + dr, nc = c + dc;
            while (0 <= nr && nr < H && 0 <= nc && nc < W) {
                if (board[nr][nc] == '*') {
                    board[nr][nc] = '.';
                    break;
                }
                if (board[nr][nc] == '#') break;
                nr += dr;
                nc += dc;
            }
        };

        for (char ch : cmd) {
            if (ch == 'U') {
                board[r][c] = '^';
                int nr = r - 1, nc = c;
                if (0 <= nr && board[nr][nc] == '.') {
                    board[nr][nc] = '^';
                    board[r][c] = '.';
                    r = nr; c = nc;
                }
            } else if (ch == 'D') {
                board[r][c] = 'v';
                int nr = r + 1, nc = c;
                if (nr < H && board[nr][nc] == '.') {
                    board[nr][nc] = 'v';
                    board[r][c] = '.';
                    r = nr; c = nc;
                }
            } else if (ch == 'L') {
                board[r][c] = '<';
                int nr = r, nc = c - 1;
                if (0 <= nc && board[nr][nc] == '.') {
                    board[nr][nc] = '<';
                    board[r][c] = '.';
                    r = nr; c = nc;
                }
            } else if (ch == 'R') {
                board[r][c] = '>';
                int nr = r, nc = c + 1;
                if (nc < W && board[nr][nc] == '.') {
                    board[nr][nc] = '>';
                    board[r][c] = '.';
                    r = nr; c = nc;
                }
            } else if (ch == 'S') {
                char dir = board[r][c];
                if (dir == '^') shoot(-1, 0);
                else if (dir == 'v') shoot(1, 0);
                else if (dir == '<') shoot(0, -1);
                else if (dir == '>') shoot(0, 1);
            }
        }

        cout << board[0];
        for (int i = 1; i < H; ++i) cout << '\n' << board[i];
        if (T) cout << '\n';
    }

    return 0;
}

