                char c = line.charAt(j);
                if (c == 'U' || c == 'D' || c == 'L' || c == 'R') {
                    tankR = i; tankC = j;
                    tankDir = c;
                    map[i][j] = '.';
                } else {
                    map[i][j] = c;
                }
            }
        }

        String ops = sc.next();

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        // U=0, D=1, L=2, R=3

        for (char op : ops.toCharArray()) {
            int dir = -1;
            if (op == 'U') dir = 0;
            else if (op == 'D') dir = 1;
            else if (op == 'L') dir = 2;
            else if (op == 'R') dir = 3;

            if (op == 'A') {
                // shoot
                int d = 0;
                if (tankDir == 'U') d = 0;
                else if (tankDir == 'D') d = 1;
                else if (tankDir == 'L') d = 2;
                else if (tankDir == 'R') d = 3;

                int r = tankR + dr[d], c = tankC + dc[d];
                while (r >= 0 && r < H && c >= 0 && c < W) {
                    if (map[r][c] == '*') {
                        map[r][c] = '.';
                        break;
                    } else if (map[r][c] == '#' || map[r][c] == '~') {
                        break;
                    }
                    r += dr[d];
                    c += dc[d];
                }
            } else {
                // move
                tankDir = op;
                int nr = tankR + dr[dir], nc = tankC + dc[dir];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && map[nr][nc] == '.') {
                    tankR = nr;
                    tankC = nc;
                }
            }
        }

        // Output
        map[tankR][tankC] = tankDir;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < H; i++) {
            sb.append(new String(map[i])).append('\n');
        }
        System.out.print(sb);
    }
}

