                    if (nr < H && map[nr][nc] == '.') {
                        map[r][c] = '.';
                        r = nr;
                        c = nc;
                        map[r][c] = dir;
                    }
                } else if (cmd == 'L') {
                    dir = '<';
                    map[r][c] = dir;
                    int nr = r, nc = c - 1;
                    if (nc >= 0 && map[nr][nc] == '.') {
                        map[r][c] = '.';
                        r = nr;
                        c = nc;
                        map[r][c] = dir;
                    }
                } else if (cmd == 'R') {
                    dir = '>';
                    map[r][c] = dir;
                    int nr = r, nc = c + 1;
                    if (nc < W && map[nr][nc] == '.') {
                        map[r][c] = '.';
                        r = nr;
                        c = nc;
                        map[r][c] = dir;
                    }
                } else if (cmd == 'S') {
                    int dr = 0, dc = 0;
                    if (dir == '^') dr = -1;
                    else if (dir == 'v') dr = 1;
                    else if (dir == '<') dc = -1;
                    else if (dir == '>') dc = 1;

                    int nr = r + dr, nc = c + dc;
                    while (nr >= 0 && nr < H && nc >= 0 && nc < W) {
                        if (map[nr][nc] == '#') {
                            break;
                        }
                        if (map[nr][nc] == '*') {
                            map[nr][nc] = '.';
                            break;
                        }
                        nr += dr;
                        nc += dc;
                    }
                }
            }

            out.append('#').append(tc).append(' ').append('\n');
            for (int i = 0; i < H; i++) {
                out.append(map[i]).append('\n');
            }
        }

        System.out.print(out);
    }
}

