import sys

def solve():
    input = sys.stdin.readline
    T = int(input().strip())

    # direction: up, down, left, right
    dr = {'U': -1, 'D': 1, 'L': 0, 'R': 0}
    dc = {'U': 0, 'D': 0, 'L': -1, 'R': 1}
    tank_char = {'U': '^', 'D': 'v', 'L': '<', 'R': '>'}
    char_to_dir = {'^': 'U', 'v': 'D', '<': 'L', '>': 'R'}

    out = []

    for tc in range(1, T + 1):
        H, W = map(int, input().split())
        board = [list(input().rstrip()) for _ in range(H)]

        N = int(input().strip())
        commands = input().strip()

        # find tank
        r = c = d = None
        for i in range(H):
            for j in range(W):
                if board[i][j] in '^v<>':
                    r, c = i, j
                    d = char_to_dir[board[i][j]]
                    break
            if r is not None:
                break

        for cmd in commands:
            if cmd in "UDLR":
                d = cmd
                board[r][c] = tank_char[d]
                nr, nc = r + dr[d], c + dc[d]
                if 0 <= nr < H and 0 <= nc < W and board[nr][nc] == '.':
                    board[r][c] = '.'
                    r, c = nr, nc
                    board[r][c] = tank_char[d]
            else:  # Shoot
                nr, nc = r, c
                while True:
                    nr += dr[d]
                    nc += dc[d]
                    if not (0 <= nr < H and 0 <= nc < W):
                        break
                    if board[nr][nc] == '#':
                        break
                    if board[nr][nc] == '*':
                        board[nr][nc] = '.'
                        break

        out.append(f"#{tc} " + ''.join(board[0]))
        for i in range(1, H):
            out.append(''.join(board[i]))

    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()
